import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 38 What are you going to do?","description":"学习 be going to 表计划，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 38 What are you going to do?","description":"学习 be going to 表计划，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 be going to 表计划，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 37 Making a bookcase","link":"/life/english/new-concept/book-1/unit-02/lesson-037"},"next":{"text":"第一册：英语初阶 · Lesson 39 Don't drop it!","link":"/life/english/new-concept/book-1/unit-02/lesson-039"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 37 Making a bookcase","link":"/life/english/new-concept/book-1/unit-02/lesson-037"},"next":{"text":"第一册：英语初阶 · Lesson 39 Don't drop it!","link":"/life/english/new-concept/book-1/unit-02/lesson-039"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/lesson-038.md","filePath":"life/english/new-concept/book-1/unit-02/lesson-038.md"}`),i={name:"life/english/new-concept/book-1/unit-02/lesson-038.md"};function r(l,e,s,h,d,g){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-38-what-are-you-going-to-do" tabindex="-1">第一册：英语初阶 · Lesson 38 What are you going to do? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-38-what-are-you-going-to-do" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 38 What are you going to do?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元 2</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-037">配套课 Lesson 37</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>区分眼前动作与未来计划 本课要掌握be going to 表计划，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>make</td><td>/meɪk/</td><td>v.</td><td>制作</td><td>make a shelf</td></tr><tr><td>bookcase</td><td>/ˈbʊkkeɪs/</td><td>n.</td><td>书柜</td><td>a wooden bookcase</td></tr><tr><td>paint</td><td>/peɪnt/</td><td>v.</td><td>涂漆</td><td>paint the door</td></tr><tr><td>hammer</td><td>/ˈhæmə/</td><td>n.</td><td>锤子</td><td>a small hammer</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be going to make — 计划制作</li><li>paint it blue — 将其刷成蓝色</li></ul><h2 id="语法讲解-be-going-to-表计划" tabindex="-1">语法讲解：be going to 表计划 <a class="header-anchor" href="#语法讲解-be-going-to-表计划" aria-label="Permalink to &quot;语法讲解：be going to 表计划&quot;">​</a></h2><p>be going to + 动词原形表示事先计划或有迹象的将来；be 随主语变化。be + 动词 ing 在本课表示当前进行。I am making 描述正在做，I am going to make 描述准备做。问计划时将 be 提前：What are you going to make?。to 后不能再用 making，时间词帮助确定语境。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I am measuring the shelf now.</p></blockquote><p>我正在测量架子。</p><p>I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>going to 后接原形，不能写 going to painting。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“I am measuring the shelf now.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I am measuring the shelf now. We are going to paint the bench tomorrow.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“区分眼前动作与未来计划”写两至三句，再读给同伴听。至少使用一次be going to 表计划，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。 We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 be：I ___ measuring the shelf now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> am</p><p><strong>解析：</strong> 按本课规则判断：be going to + 动词原形表示事先计划或有迹象的将来；be 随主语变化。be + 动词 ing 在本课表示当前进行。I am making 描述正在做，I am going to make 描述准备做。问计划时将 be 提前：What are you going to make?。to 后不能再用 making，时间词帮助确定语境。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我正在测量架子。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I am measuring the shelf now.</p><p><strong>解析：</strong> I am measuring 是现在进行时，now 强调眼前动作；它与计划结构 going to measure 的时间视角不同。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：We are going to paint the bench tomorrow.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我们准备明天给长凳刷漆。</p><p><strong>解析：</strong> We are going to paint 表计划，paint 用原形；the bench 为宾语，tomorrow 把计划放在明天。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：be going to 表计划。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-037">上一课</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-039">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(i,[["render",r]]);export{p as __pageData,u as default};
